const icons = {
 arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>', chevron:'<path d="m7 10 5 5 5-5"/>', laptop:'<rect x="5" y="4" width="14" height="12" rx="2"/><path d="M2 20h20l-3-4H5Z"/>', spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>', check:'<path d="m5 12 4 4L19 6"/>', grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>', bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>', code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16"/>', heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', external:'<path d="M14 3h7v7m0-7L10 14m-1-9H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-4"/>', back:'<path d="M20 12H4m6-6-6 6 6 6"/>', save:'<path d="M6 3h12v18l-6-4-6 4Z"/>', send:'<path d="m3 3 18 9-18 9 4-9-4-9Zm4 9h14"/>', copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>', search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>', tune:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>', moon:'<path d="M20 14a9 9 0 0 1-10-11 9 9 0 1 0 10 11Z"/>', book:'<path d="M3 3h6l3 2 3-2h6v17h-6l-3 1-3-1H3Zm9 2v16"/>'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc = s => String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app');
const read=readPreference;
const write=(key,value)=>{const persisted=writePreference(key,value);if(!persisted)toast('Settings apply for this visit. Browser storage is unavailable.');return persisted;};
const writeSavedBuilds=value=>{try{localStorage.setItem('macfit.builds',JSON.stringify(value));return true;}catch{toast('Could not save changes. Browser storage is unavailable.');return false;}};
let profile=read('macfit.profile',defaultProfile);
let disposeRecommendation=null,disposePageFocus=null;
const profileConfirmed=()=>{const proof=read('macfit.recommendation.profile',null);return proof?.confirmed===true&&proof.deviceId===profile.deviceConfigId&&Number.isFinite(Date.parse(proof.confirmedAt));};
let saved=[],currentBuild=null,search='',category='all',publisher='all',listPage=1,sort='popular',quantTab='planner',chat=[],compare=false,vote='',busy=false,chatRun=0;
let wizardUse='General',wizardPreference='Balanced';
let deviceContext=Number(read('macfit.context',8192)),fitFilter='all',matchState={key:null,status:'idle',items:[],error:null},matchController=null;
const configRows=()=>configurations(hardware);
const selectedConfiguration=()=>configRows().find(c=>c.id===profile.deviceConfigId);
const matchContext=()=>location.pathname.startsWith('/build/')||location.pathname.startsWith('/play/')?currentBuild?.context:deviceContext;
const buildScope=()=>location.pathname.startsWith('/build/')||location.pathname.startsWith('/play/')?currentBuild?.model:null;
const liveKey=()=>profile.deviceConfigId+'|'+matchContext()+'|'+(buildScope()||'all');
const fmt=(v,d=1)=>v==null?'Unknown':Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
const compact=v=>v==null?'—':Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(v);
const ctx=v=>contextLabel({context_length:v});
const modelFor=b=>catalog.models.find(m=>m.id===b.model);
const quantFor=b=>quants.find(q=>q.id===b.quant);
const parseBuild=id=>decodeBuild(id,catalog.models);
const plan=b=>memoryPlan(modelFor(b),quantFor(b),b.context,profile);
const buildLink=(b,path='build')=>`/${path}/${buildId(b)}`;
const source=id=>catalog.sources.find(s=>s.id===id);
const device=id=>catalog.devices.find(d=>d.id===id);
const titleCase=t=>catalog.categories.find(c=>c.id===t)?.label||t;
const categoryTags=m=>(m.task_tags||[]).map(t=>titleCase(t));
const profileLabel=()=>{if(!profileConfirmed())return 'Confirm your device';const c=selectedConfiguration();return c?`${esc(c.chip.name.replace(/^Apple /,''))} · ${fmt(c.chip.memory_kind==='discrete'?c.vram_gib:c.ram_gib)}GB`:'Choose a device';};
const logo=m=>`<span class="model-logo ${['Google','google'].includes(m.owner)?'blue':m.owner?.toLowerCase().includes('qwen')?'violet':'green'}">${esc((m.owner||m.name).slice(0,1).toUpperCase())}</span>`;
const isCatalog=()=>location.pathname==='/models';
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2800);}
function sourceLink(id,label='Source'){const s=source(id);return s?`<a class="inline-link source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" title="${esc(s.title)}">${esc(label)} ${icon('external')}</a>`:'<span class="muted-text">Source unavailable</span>';}
function header(){const path=location.pathname;return `<header class="site-header"><a class="brand" href="/" aria-label="MacFit home"><img src="/favicon.svg" alt=""/>MacFit</a><nav aria-label="Main navigation"><a href="/teach" ${path==='/teach'||path.startsWith('/customize/')?'aria-current="page"':''}>Teach a model</a><a href="/models" ${isCatalog()?'aria-current="page"':''}>Models</a><a href="/for-your-device" ${path==='/for-your-device'||path.startsWith('/optimize/')?'aria-current="page"':''}>For your device</a></nav>${accountControl()}</header>`;}

function closeAccountMenu(restoreFocus=false){const panel=document.querySelector('#account-panel'),trigger=document.querySelector('#account-trigger');if(!panel||panel.hidden)return;panel.hidden=true;trigger?.setAttribute('aria-expanded','false');if(restoreFocus)trigger?.focus();}

function footer(){return `<footer><a class="brand small" href="/"><img src="/favicon.svg" alt=""/>MacFit</a><span>Models, hardware, and the evidence between them.</span><span class="demo-label">${catalog.models.length} base models · ${catalog.benchmarks.filter(b=>b.model_id).length} linked measurements</span></footer>`;}
function picker(inDialog=false){
 const prefix=inDialog?'modal-':'',selected=selectedConfiguration();
 const chips=hardware.items.filter(c=>(c.memory_kind==='unified'?'mac':'pc')===profile.family);
 const chip=chips.find(c=>c.id===selected?.chip_id)||chips[0];
 return `<div class="picker-heading"><span class="icon-box">${icon('laptop')}</span><div><h2>Your device. Your starting point.</h2><p>Choose a recorded hardware configuration.</p></div></div><label class="field-label">Device family</label><div class="segmented">${[['mac','Mac'],['pc','PC']].map(([id,label])=>`<button data-family="${id}" class="${profile.family===id?'active':''}" aria-pressed="${profile.family===id}">${icon('laptop')}${label}</button>`).join('')}</div><label class="field-label" for="${prefix}db-chip">Chip / GPU</label><select id="${prefix}db-chip" data-field="db-chip">${chips.map(c=>`<option value="${esc(c.id)}" ${c.id===chip?.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label class="field-label">${chip?.memory_kind==='discrete'?'GPU memory':chip?.memory_kind==='system'?'System memory':'Unified memory'}<span>GB</span></label><div class="memory-options">${(chip?.configurations||[]).map(c=>`<button data-config="${esc(c.id)}" class="${profile.deviceConfigId===c.id?'selected':''}" aria-pressed="${profile.deviceConfigId===c.id}">${fmt(chip.memory_kind==='discrete'?c.vram_gib:c.ram_gib)}</button>`).join('')}</div><div class="database-profile-note">${icon('book')} ${esc(selected?.device_class||'Documented configuration')}<span>${selected?.memory_bandwidth_gbps?fmt(selected.memory_bandwidth_gbps)+' GB/s memory bandwidth':'Bandwidth not recorded'}</span></div><button class="button primary full picker-submit" data-action="${inDialog?'save-profile':'find'}">${inDialog?'Use this device':'Find models for this device'} ${icon('arrow')}</button><p class="picker-note">${hardware.items.length} chips · ${configRows().length} sourced configurations</p>`;
}
function home(){return `<main class="home product-home"><section class="product-hero"><div class="product-hero-copy"><div class="eyebrow"><span class="status-dot"></span> YOUR EXAMPLES. YOUR WAY OF WORKING.</div><h1>A little teaching.<br/>A model <em>that’s yours.</em></h1><p>Start with a task. Build good teaching data.<br/>Make a small model work your way.</p><div class="teach-home-cta"><a class="button primary" href="/teach">Teach my model ${icon('arrow')}</a><a href="/for-your-device">Find a model for my computer</a></div><span class="hero-caption">Try the guided preview. No code or training experience needed.</span></div><div class="hero-scene" aria-label="From your computer to your own model"><div class="scene-orbit"></div><div class="scene-device card"><span class="scene-mini-label">01 · CHOOSE YOUR MODEL</span><div class="scene-computer">${icon('laptop')}</div><h3>Your computer</h3><p>Mac or PC. Built around your memory.</p><div class="scene-spec"><span>Hardware</span><strong>Yours.</strong></div><div class="scene-spec"><span>Possibilities</span><strong>Let's find them.</strong></div></div><div class="scene-personal"><span class="scene-spark">✦</span><div><span class="scene-mini-label">02 · TEACH IT YOUR WAY</span><h3>Your way of working.</h3><p>Your instructions. Your examples.</p></div></div><span class="scene-label">GOOD TOGETHER.</span></div></section><section class="product-steps"><div><span>01</span><h2>Start with your task.</h2><p>Tell us what you want it to do. Choose a model and understand its limits.</p></div><div><span>02</span><h2>Show it good answers.</h2><p>Preview and correct a few examples, then prepare and review the full dataset.</p></div><div><span>03</span><h2>Train. Then check.</h2><p>Choose a model and compare on separate test questions before using the result.</p></div></section></main>`;}

function filters(){return `<div class="filter-tabs catalog-tabs" role="tablist" aria-label="Model capability">${[{id:'all',label:'All models'},...catalog.categories].map(c=>`<button role="tab" aria-selected="${category===c.id}" data-category="${c.id}" class="${category===c.id?'active':''}">${c.id==='coding'?icon('code'):c.id==='thinking'?icon('spark'):''}${esc(c.label)}</button>`).join('')}</div>`;}
function filteredModels(){return filterCatalog(catalog.models,{search,category,publisher,sort});}
function catalogCard(m){return `<article class="model-card catalog-model card"><div class="model-card-heading">${logo(m)}<div><a href="/model/${m.id}"><h3>${esc(m.name)}</h3></a><span>${esc(m.owner)}</span></div><a class="icon-button" aria-label="View ${esc(m.name)}" href="/model/${m.id}">${icon('arrow')}</a></div><p class="catalog-description">${esc(m.description||'Model details have not been verified yet.')}</p><dl class="catalog-specifications"><div title="${esc(fieldNote(m,'parameter_count'))}"><dt>Parameters</dt><dd>${esc(parameterLabel(m))}</dd></div><div title="${esc(fieldNote(m,'context_length'))}"><dt>${m.field_evidence?.context_length?.basis==='publisher-tokenizer-limit'?'Tokenizer limit':m.field_evidence?.context_length?.basis==='publisher-training-context'?'Training context':'Context window'}</dt><dd>${esc(contextLabel(m))}${m.context_length?'<small> tokens</small>':''}</dd></div></dl><div class="tags">${categoryTags(m).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="catalog-downloads"><span>HF downloads <small>· last 30 days</small></span><strong>${compact(m.downloads_30d)}</strong></div><div class="catalog-footer"><span class="catalog-license"><small>License</small><span>${esc(licenseLabel(m.license))}</span></span><a href="https://huggingface.co/${esc(m.hf_id)}" target="_blank" rel="noopener noreferrer">Model card ${icon('external')}</a></div></article>`;}
function buildFromAssessment(m,row){return {...defaultBuild(m,profile),quant:row.quantization,artifact:row.artifact_id,context:Number(row.context_tokens)};}
function deviceCard(m){
 const rows=matchState.groups?.get(m.id)||[{model_id:m.id,verdict:'unknown',context_tokens:deviceContext,reason:'Model is cataloged; no verified artifact/runtime assessment yet.'}];
 const displayed=fitFilter==='all'?rows:rows.filter(r=>r.verdict===fitFilter);
 const row=preferredOption(displayed)||displayed.find(r=>['weights_fit_kv_unverified','weights_fit_context_unverified'].includes(r.memory_status))||displayed.find(r=>r.artifact_id)||displayed[0];
 if(!row)return '';
 const status=assessmentLabel(row);
 const total=row.estimated_required_bytes==null?null:Number(row.estimated_required_bytes)/1024**3;
 const weight=row.artifact_bytes==null?null:Number(row.artifact_bytes)/1024**3;
 const b=row.artifact_id&&quants.some(q=>q.id===row.quantization)?buildFromAssessment(m,row):null;
 return `<article class="model-card device-model card"><div class="model-card-heading">${logo(m)}<div><a href="/model/${m.id}"><h3>${esc(m.name)}</h3></a><span>${esc(m.owner)} · ${esc(parameterLabel(m))}</span></div></div><p>${esc(m.description||'Publisher specifications and evidence available in the model details.')}</p><div class="evidence-fit ${row.verdict==='planning_candidate'?'good':row.verdict==='insufficient_memory'?'poor':'unknown'}">${icon('book')} ${status}</div><div class="device-evidence"><div><span>Recorded configuration</span><strong>${esc(row.quantization||'No artifact recorded')}</strong></div><div><span>Weight files</span><strong>${weight==null?'Unknown':fmt(weight,2)+' GiB'}</strong></div><div><span>Total planning budget</span><strong>${total==null?'Not assessed':fmt(total,2)+' GiB'}</strong></div><div><span>Generation speed</span><strong>Not measured here</strong></div></div><div class="measurement-caption">${esc(row.runtime||'Runtime not recorded')} · ${ctx(Number(row.context_tokens))} context · ${rows.filter(r=>r.artifact_id).length} recorded options</div><div class="tags">${categoryTags(m).slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><details class="fit-reason"><summary>Why this result?</summary><p>${esc(row.reason)}</p>${row.artifact_source_id?sourceLink(row.artifact_source_id,'File evidence'):''}</details><div class="card-actions"><a class="button ${b?'secondary':'primary'}" href="/model/${m.id}">Model details ${icon('arrow')}</a>${b?`<a class="button primary" href="${buildLink(b)}">Inspect build</a>`:''}</div></article>`;
}
function liveDeviceControls(){return `<section class="live-device-controls card"><div><span class="field-label">Selected device</span><button class="device-selector-inline" data-action="profile">${icon('laptop')} ${profileLabel()} ${icon('chevron')}</button></div><div><label class="field-label" for="device-context">Context window</label><select id="device-context">${hardware.contexts.map(n=>`<option value="${n}" ${Number(n)===deviceContext?'selected':''}>${ctx(Number(n))} tokens</option>`).join('')}</select></div><div><label class="field-label" for="fit-filter">Show</label><select id="fit-filter"><option value="planning_candidate" ${fitFilter==='planning_candidate'?'selected':''}>Planning candidates</option><option value="all" ${fitFilter==='all'?'selected':''}>All results</option><option value="insufficient_memory" ${fitFilter==='insufficient_memory'?'selected':''}>Over budget</option><option value="unknown" ${fitFilter==='unknown'?'selected':''}>Not assessed / incomplete evidence</option></select></div><button class="button secondary refresh-data" data-action="refresh-matches">Refresh</button></section>`;}
function deviceModels(){return filteredModels().filter(m=>{const rows=matchState.groups?.get(m.id)||[];return fitFilter==='all'||(fitFilter==='unknown'&&!rows.length)||rows.some(r=>r.verdict===fitFilter);});}
function pageFor(models){const result=paginateModels(models,listPage);if(result.page!==listPage){listPage=result.page;updateQuery();}return result;}
function paginationMarkup(models){const p=pageFor(models);return `<nav class="catalog-pagination" aria-label="Model pages"><span>${fmt(p.start,0)}–${fmt(p.end,0)} of ${fmt(p.total,0)} models · Page ${p.page} of ${p.pages}</span><div><button class="button secondary" data-page="1" ${p.page===1?'disabled':''}>First</button><button class="button secondary" data-page="${p.page-1}" ${p.page===1?'disabled':''}>Previous</button><button class="button secondary" data-page="${p.page+1}" ${p.page===p.pages?'disabled':''}>Next</button><button class="button secondary" data-page="${p.pages}" ${p.page===p.pages?'disabled':''}>Last</button></div></nav>`;}
function liveResults(){
 if(matchState.key!==liveKey()||matchState.status==='loading'||matchState.status==='idle')return `<div class="empty loading-results" role="status"><span class="loading-indicator"></span><h2>Checking your device…</h2><p>${matchState.progress?`${fmt(matchState.progress.loadedModels,0)} of ${fmt(matchState.progress.totalModels,0)} models loaded`:'Reading the recorded configuration assessments.'}</p></div>`;
 if(matchState.status==='unsupported')return '<div class="empty"><h2>This context has no recorded assessment.</h2><p>Select a recorded context size to see database results.</p></div>';
 if(matchState.status==='error')return `<div class="empty" role="alert"><h2>We couldn’t load the assessments.</h2><p>${esc(matchState.error||'The assessment service is temporarily unavailable.')}</p><button class="button primary" data-action="refresh-matches">Try again</button></div>`;
 const ms=deviceModels();return pageFor(ms).items.map(deviceCard).join('')||'<div class="empty"><h2>No matching results.</h2><p>Try another search, publisher, capability or show all results.</p><button class="button secondary" data-action="reset-filters">Reset filters</button><button class="button secondary" data-action="show-all-fits">Show all results</button></div>';
}
async function ensureMatches(force=false){
 const context=Number(matchContext()),key=liveKey();
 if(!profile.deviceConfigId)return;
 if(!hardware.contexts.map(Number).includes(context)){matchController?.abort();matchState={key,status:'unsupported',items:[],error:null};refreshDatabaseSections();return;}
 if(!force&&matchState.key===key&&['ready','loading','error'].includes(matchState.status)){refreshDatabaseSections();return;}
 matchController?.abort();const controller=new AbortController();matchController=controller;
 matchState={key,status:'loading',items:[],error:null};refreshDatabaseSections();
 try{
  const result=await fetchCompatibility(profile.deviceConfigId,context,{signal:controller.signal,modelId:buildScope(),onProgress:progress=>{if(!controller.signal.aborted&&key===liveKey()){matchState.progress=progress;refreshDatabaseSections();}}});
  if(controller.signal.aborted||key!==liveKey())return;
  if(!Array.isArray(result.items))throw new Error('Invalid assessments');
  matchState={key,status:'ready',items:result.items,groups:groupAssessments(result.items),counts:result.counts,error:null,catalog_revision:result.catalog_revision};
 }catch(error){if(controller.signal.aborted||key!==liveKey())return;matchState={key,status:'error',items:[],error:error.message||'Database unavailable'};}
 refreshDatabaseSections();
}
function refreshDatabaseSections(){
 if(location.pathname==='/for-your-device'){
  const grid=document.querySelector('#model-grid');if(grid)grid.innerHTML=liveResults();
  const count=document.querySelector('#result-count');if(count)count.textContent=matchState.status==='ready'&&matchState.key===liveKey()?fmt(deviceModels().length,0)+' results after filters · '+fmt(catalog.models.length,0)+' in catalog':matchState.status==='error'?'Database unavailable':'Checking database…';
  const stats=document.querySelector('#device-result-stats');if(stats){const candidates=matchState.items.filter(r=>r.verdict==='planning_candidate');const weightFits=matchState.items.filter(r=>['weights_fit_kv_unverified','weights_fit_context_unverified'].includes(r.memory_status));stats.textContent=matchState.status==='ready'?`Device totals · ${new Set(candidates.map(r=>r.model_id)).size} candidate models · ${candidates.filter(r=>r.artifact_id).length} candidate quant options · ${weightFits.length} options with weight space, runtime unverified`:'';}
  const pager=document.querySelector('#catalog-pages');if(pager)pager.innerHTML=matchState.status==='ready'&&matchState.key===liveKey()?paginationMarkup(deviceModels()):'';
 }
 const summaryEl=document.querySelector('#summary');if(summaryEl&&currentBuild)summaryEl.innerHTML=summary(currentBuild);
 const playMeter=document.querySelector('.play-build .memory-meter');if(playMeter&&currentBuild)playMeter.outerHTML=memoryMeter(currentBuild,true);
}
function listing(catalogOnly){const publishers=[...new Set(catalog.models.map(m=>m.owner).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return `<main class="page results-page"><div class="page-intro"><div><div class="eyebrow">${catalogOnly?'THE ORIGINAL MODELS':'START WITH YOUR HARDWARE'}</div><h1>${catalogOnly?'Models, in one place.':'For your device.'}</h1><p>${catalogOnly?'Explore publisher checkpoints, including recent releases.':`${profileLabel()} · Original models and their recorded quantized builds.`}</p></div>${catalogOnly?`<span class="subtle-badge">${fmt(catalog.models.length,0)} base models</span>`:`<button class="button secondary" data-action="profile">${icon('laptop')} Change device</button>`}</div>${!catalogOnly?liveDeviceControls():''}${filters()}<div class="results-toolbar"><div class="preferences"><label for="model-sort">Sort by</label><select id="model-sort">${[['popular','HF downloads'],['newest','Newest on Hub'],['updated','Recently updated'],['smallest','Parameter count']].map(([value,label])=>`<option value="${value}" ${sort===value?'selected':''}>${label}</option>`).join('')}</select><label for="publisher-filter">Publisher</label><select id="publisher-filter"><option value="all">All publishers</option>${publishers.map(p=>`<option value="${esc(p)}" ${publisher===p?'selected':''}>${esc(p)}</option>`).join('')}</select></div><label class="search-box">${icon('search')}<input id="model-search" type="search" placeholder="Model or publisher…" aria-label="Find a model" value="${esc(search)}"/></label></div>${!catalogOnly?`<div class="evidence-banner">${icon('book')}<span>Large models can fit through smaller 4-bit files. Results use recorded artifact bytes, context/KV evidence and system reserve. “Not assessed” means evidence is missing. Planning candidates still need runtime validation.</span></div><p class="device-result-stats" id="device-result-stats"></p>`:''}<div class="result-heading"><span id="result-count">${catalogOnly?fmt(filteredModels().length,0)+' models':'Checking database…'}</span><span>Synced ${esc((catalog.coverage?.completed_at||catalog.generated_at||'').slice(0,10))}</span></div><div class="model-grid" id="model-grid">${catalogOnly?listCards(true):liveResults()}</div><div id="catalog-pages">${catalogOnly?paginationMarkup(filteredModels()):''}</div><p class="fixture-note">Categories follow publisher tasks and sourced capabilities. Downloads are an observed popularity signal, not a quality score. ${catalogOnly?'Quantized files and runtime settings appear on each model’s detail page.':''}</p></main>`;}
function listCards(catalogOnly){return pageFor(filteredModels()).items.map(catalogOnly?catalogCard:deviceCard).join('')||'<div class="empty"><h2>No matching models.</h2><p>Try another name, publisher or capability.</p><button class="button secondary" data-action="reset-filters">Reset filters</button></div>';}
function buildAssessment(b){
 const expected=profile.deviceConfigId+'|'+b.context+'|'+b.model;
 if(matchState.key!==expected||matchState.status==='loading'||matchState.status==='idle')return {state:'loading',row:null};
 if(matchState.status==='error')return {state:'error',row:null};
 if(matchState.status==='unsupported')return {state:'unsupported',row:null};
 const row=assessmentForBuild(matchState.items,b);return {state:row?'ready':'missing',row};
}
function memoryMeter(b,compactOnly=false){
 const {state,row}=buildAssessment(b),c=selectedConfiguration();
 const capacity=Number(c?.chip.memory_kind==='discrete'?c?.vram_gib:c?.ram_gib)||null;
 if(!row){const text=state==='loading'?'Loading the recorded assessment…':state==='error'?'Assessment service unavailable':state==='unsupported'?'This context has no recorded assessment.':'No stored assessment for this model and format.';
 return `<div class="memory-meter"><div class="meter-title"><span>${c?.chip.memory_kind==='discrete'?'GPU memory':'Unified memory'}</span><strong>${capacity?fmt(capacity)+' GB':'Unknown'}</strong></div><div class="db-assessment-empty" role="status">${icon('book')} ${text}</div>${state==='error'?'<button class="inline-link" data-action="refresh-matches">Retry</button>':''}<p class="micro-note">No fit conclusion is shown without a matching assessment.</p></div>`;}
 const gib=n=>n==null?null:Number(n)/1024**3,weight=gib(row.artifact_bytes),kv=gib(row.kv_cache_bytes),reserve=gib(row.policy_reserve_bytes),total=gib(row.estimated_required_bytes),headroom=gib(row.headroom_bytes);
 const pct=n=>capacity&&n!=null?Math.max(0,n/capacity*100):0;
 return `<div class="memory-meter ${compactOnly?'compact':''}"><div class="meter-title"><span>Stored memory plan</span><strong>${total==null?'Unknown':fmt(total,2)} <span>/ ${fmt(capacity)} GiB</span></strong></div><div class="memory-track" role="img" aria-label="${weight==null?'Unknown weight file size':fmt(weight,2)+' GiB weight files'}, ${kv==null?'unknown KV cache':fmt(kv,2)+' GiB KV cache'}, ${fmt(reserve,2)} GiB reserved"><span class="mem-model" style="width:${pct(weight)}%"></span><span class="mem-context" style="width:${pct(kv)}%"></span><span class="mem-os" style="width:${pct(reserve)}%"></span></div>${compactOnly?'':`<div class="memory-legend"><span><i class="mem-model"></i>Recorded weight files<b>${weight==null?'Unknown':fmt(weight,2)+' GiB'}</b></span><span><i class="mem-context"></i>FP16 KV cache estimate<b>${kv==null?'Unknown':fmt(kv,2)+' GiB'}</b></span><span><i class="mem-os"></i>System / runtime reserve<b>${fmt(reserve,2)} GiB</b></span><span><i class="mem-free"></i>${headroom!=null&&headroom<0?'Over budget':'Planning headroom'}<b>${headroom==null?'Unknown':fmt(Math.abs(headroom),2)+' GiB'}</b></span></div>`}<div class="fit ${row.verdict==='planning_candidate'?'good':row.verdict==='insufficient_memory'?'poor':'unknown'}">${icon('book')} ${esc(assessmentLabel(row))}</div><p class="micro-note">${esc(row.reason)}</p></div>`;
}

function benchmarkTable(m){const rows=catalog.benchmarks.filter(b=>b.model_id===m.id);if(!rows.length)return `<div class="empty evidence-empty"><span class="empty-mark">${icon('book')}</span><h3>No hardware measurements imported yet.</h3><p>This model is in the catalog. Its cross-device performance is still unknown.</p><a class="inline-link" href="#requirements">View documented specifications ${icon('arrow')}</a></div>`;return `<div class="table-wrap card"><table class="benchmark-table"><thead><tr><th>Published hardware</th><th>Format / runtime</th><th>Prompt processing</th><th>Generation</th><th>Peak allocation</th><th>Workload</th><th>Evidence</th></tr></thead><tbody>${rows.map(b=>{const d=device(b.device_id);return `<tr><td><strong>${esc(d?.name||b.device_id)}</strong><span class="table-sub">${esc(d?.inference_mode==='cpu'?d?.cpu||'CPU':d?.gpu||d?.cpu||'')} ${d?.memory_gb?'· '+d.memory_gb+' GB RAM':''} ${d?.vram_gb&&d?.inference_mode!=='cpu'?'· '+d.vram_gb+' GB VRAM':''}</span></td><td>${esc(b.quantization||'Not reported')}<span class="table-sub">${esc(b.runtime||'')} ${esc(b.runtime_version||'Version not reported')}</span></td><td>${b.prompt_tokens_per_second==null?'Not reported':fmt(b.prompt_tokens_per_second)+' tok/s'}</td><td>${b.generation_tokens_per_second==null?'Not reported':fmt(b.generation_tokens_per_second)+' tok/s'}</td><td>${b.peak_memory_gb==null?'Not reported':fmt(b.peak_memory_gb,2)+' GB'}<span class="table-sub">${b.peak_memory_gb==null?'':'Reported runtime allocation; not total RAM'}</span></td><td>${b.test_protocol==='separate_pp_tg'?`PP${b.prompt_tokens??'?'} / TG${b.output_tokens??'?'} (separate)`:b.test_protocol==='sequential_generate'?`${b.prompt_tokens??'?'} input → ${b.output_tokens??'?'} generated`:'Protocol not fully reported'}<span class="table-sub">Context: ${b.context_tokens==null?'not reported':b.context_tokens}</span></td><td>${sourceLink(b.source_id)}<span class="table-sub">${esc((b.evidence_type||'reported').replaceAll('_',' '))}</span></td></tr>`;}).join('')}</tbody></table></div><div class="measurement-notes">${rows.map(b=>`<details><summary>${esc(device(b.device_id)?.name||b.device_id)} · test conditions</summary><p>${esc(b.notes||'No further notes reported.')}</p><p>Batch: ${b.batch_size??'not reported'} · GPU layers: ${esc(b.gpu_layers??'not reported')} · Date: ${esc(b.measured_at||'not reported')} · ${esc(b.source_locator||'')}</p></details>`).join('')}</div>`;}
function publisherGuidance(m){const rows=(catalog.runtime_requirements||[]).filter(r=>r.model_id===m.id);return rows.length?`<section class="public-guidance"><h3>Publisher runtime guidance</h3><p>These are the publisher’s stated recommendations under the conditions below, not universal minimums.</p><ul>${rows.map(r=>`<li><strong>${esc(r.runtime)} · ${r.required_vram_gb?fmt(r.required_vram_gb)+' GB VRAM':r.required_unified_memory_gb?fmt(r.required_unified_memory_gb)+' GB unified memory':r.required_ram_gb?fmt(r.required_ram_gb)+' GB RAM':'See source'}</strong> — ${sourceLink(r.source_id)}<p>${esc(r.notes)}</p></li>`).join('')}</ul></section>`:'';}
function modelInformation(m){
 const list=values=>Array.isArray(values)&&values.length?values.map(esc).join(', '):'Not verified';
 const fieldSource=field=>{const evidence=m.field_evidence?.[field];return `<span class="field-evidence-note">${esc(fieldNote(m,field))}${evidence?.url?` <a href="${esc(evidence.url)}" target="_blank" rel="noopener noreferrer">Verify source</a>`:''}</span>`;};
 const row=(label,value)=>`<div><dt>${label}</dt><dd>${value}</dd></div>`;
 return `<section class="card publisher-information"><h2>Model information</h2><dl class="publisher-information-grid">${row('Task',esc(m.pipeline_tag||'Not verified'))}${row('Languages',list(m.languages))}${row('Model family / architecture type',esc(m.model_type||m.architecture||'Not disclosed'))}${row('Library',esc(m.library_name||'Not verified'))}${row('Training datasets declared by publisher',list(m.training_datasets))}${row('Base models declared by publisher',list(m.base_model_repositories))}${row('Parameters · source & method',`${esc(parameterLabel(m))}${fieldSource('parameter_count')}`)}${row('Context · source & method',`${esc(contextLabel(m))}${m.context_length?' tokens':''}${fieldSource('context_length')}${m.context_variants_source_url?` <a href="${esc(m.context_variants_source_url)}" target="_blank" rel="noopener noreferrer">Checkpoint specifications</a>`:''}`)}${row('Weight access',esc(m.weights_access==='gated'?'Publisher approval required':m.weights_access==='public-files-listed'?'Public weight files listed':'Not verified'))}${row('Repository revision',esc(m.repository_revision?.slice(0,12)||'Not recorded'))}${row('Repository created',esc(m.repository_created_at?.slice(0,10)||'Not recorded'))}${row('Metadata checked',esc(m.metadata_checked_at?.slice(0,10)||m.metadata_observed_at?.slice(0,10)||'Not recorded'))}</dl><p class="micro-note">Repository creation is not a verified release date. Unverified means the available publisher metadata did not establish this field. Config-based parameter calculations are labeled estimates; hardware performance requires separate measurements.</p></section>`;
}
function detail(m){const b=defaultBuild(m,profile),rows=catalog.benchmarks.filter(r=>r.model_id===m.id);return `<main class="page detail-page"><a class="back-link" href="/models">${icon('back')} All models</a><div class="detail-heading">${logo(m)}<div><div class="eyebrow">${esc(m.owner)} · ${m.context_variants?.length?'CHECKPOINT COLLECTION':'ORIGINAL MODEL'}</div><h1>${esc(m.name)}</h1><div class="detail-meta"><span>${esc(licenseLabel(m.license))}</span><a href="https://huggingface.co/${esc(m.hf_id)}" target="_blank" rel="noopener noreferrer">Publisher model card ${icon('external')}</a></div></div>${!isEmbedding(m)?`<a class="button primary" href="/optimize/${esc(m.id)}">Find a version for my computer ${icon('arrow')}</a><a class="button secondary" href="/teach?model=${encodeURIComponent(m.id)}">Teach this model</a>`:'<span class="subtle-badge">Embedding model · no chat generation</span>'}</div><p class="detail-description">${esc(m.description||'Publisher model specifications available in the model card.')}</p>${m.description_basis==='publisher-excerpt'?`<p class="description-attribution">Publisher excerpt · <a href="${esc(m.description_source_url)}" target="_blank" rel="noopener noreferrer">Read the full model card</a></p>`:''}<div class="tags">${categoryTags(m).map(t=>`<span>${esc(t)}</span>`).join('')}</div><section id="requirements" class="detail-overview"><div class="card capability-card"><div class="section-heading"><h2>Publisher specifications</h2><span class="subtle-badge">Sourced</span></div><dl class="spec-list"><div><dt>Parameters</dt><dd>${esc(parameterLabel(m))}</dd></div><div><dt>${m.field_evidence?.context_length?.basis==='publisher-tokenizer-limit'?'Tokenizer limit':m.field_evidence?.context_length?.basis==='publisher-training-context'?'Training context':'Documented context'}</dt><dd>${esc(contextLabel(m))}${m.context_length?' tokens':''}</dd></div><div><dt>Architecture</dt><dd>${esc(m.architecture||'Not published')}</dd></div><div><dt>HF downloads / 30 days</dt><dd>${fmt(m.downloads_30d,0)}</dd></div><div><dt>License</dt><dd>${esc(licenseLabel(m.license))}</dd></div></dl><div class="sources-row">${(m.source_ids||[]).map(id=>sourceLink(id,source(id)?.title?.includes('config')?'Config':'Source')).join(' ')}</div></div><div class="card fit-card"><div class="eyebrow">WEIGHT STORAGE LOWER BOUNDS</div><h2>Before runtime overhead.</h2><p>Calculated from parameter count × bits ÷ 8. These are not minimum system requirements.</p><div class="weight-floors">${[16,8,4].map(bits=>`<div><span>${bits}-bit</span><strong>${weightsFloor(m,bits)==null?'Unknown':fmt(weightsFloor(m,bits))+' GiB'}</strong></div>`).join('')}</div><p class="micro-note">${esc(m.notes||'Actual artifact size and running memory depend on precision, context, architecture, and runtime.')}</p></div></section>${modelInformation(m)}${publisherGuidance(m)}<section class="quant-section" id="performance"><div class="section-heading"><div><div class="eyebrow muted">MEASUREMENTS KEEP THEIR CONTEXT</div><h2>Across hardware</h2></div><span class="muted-text">${rows.length} published records</span></div><p class="section-description">Reported prompt processing and generation are separate metrics. Different runtime versions or workloads are not a controlled like-for-like comparison.</p>${benchmarkTable(m)}</section>${!isEmbedding(m)?`<section class="quant-section" id="quants"><div class="section-heading"><div><div class="eyebrow muted">SEPARATE FROM THE BASE MODEL</div><h2>Recorded builds</h2></div></div><p class="section-description">File sizes and revisions come from the recorded artifact repositories. Inspect a build to see its assessment for your selected device.</p>${(catalog.artifacts||[]).some(a=>a.model_id===m.id)?`<div class="quant-planner-grid">${catalog.artifacts.filter(a=>a.model_id===m.id).map(a=>`<a class="card quant-planner" href="${buildLink({...b,quant:a.quantization,artifact:a.id,context:Math.min(deviceContext,modelLimit(m)??deviceContext)})}"><strong>${esc(a.quantization)}</strong><span>${esc(a.format)} · ${esc(a.runtime_family)}</span><p>${fmt(Number(a.actual_size_bytes)/1024**3,2)} GiB</p><span>Revision ${esc(a.revision?.slice(0,8)||'not recorded')}</span>${icon('arrow')}</a>`).join('')}</div>`:'<div class="empty evidence-empty"><h3>No artifact files recorded yet.</h3><p>The original model is in the catalog. A verified runtime build still needs to be added.</p></div>'}</section>`:''}<p class="fixture-note">Last metadata snapshot: ${esc((m.popularity_observed_at||'').slice(0,10))}. No synthetic capability scores or extrapolated hardware throughput.</p></main>`;}
function summary(b){const m=modelFor(b),{state,row}=buildAssessment(b);return `<aside class="build-summary card"><div class="eyebrow">YOUR CONFIGURATION</div><div class="summary-model">${logo(m)}<div><h2>${esc(m.name)}</h2><p>${esc(b.quant)} · ${ctx(b.context)} context</p></div></div><div class="summary-profile">${icon('laptop')}${profileLabel()}</div><div class="summary-experience"><span>Memory assessment</span><strong class="${row?.verdict==='planning_candidate'?'good':row?.verdict==='insufficient_memory'?'poor':'unknown'}">${row?esc(assessmentLabel(row)):state==='loading'?'Checking…':'Not assessed'}</strong></div><div class="summary-numbers"><div><span>Recorded file size</span><strong>${row?.artifact_bytes==null?'—':fmt(Number(row.artifact_bytes)/1024**3,2)}<small> GiB</small></strong></div><div><span>Device throughput</span><strong class="unknown-speed">Not measured</strong></div></div>${memoryMeter(b)}${row?.artifact_url?`<a class="inline-link summary-source" href="${esc(row.artifact_url)}" target="_blank" rel="noopener noreferrer">Recorded artifact ${icon('external')}</a>`:''}<a class="button primary full" href="${b.artifact?'/run/'+encodeURIComponent(b.artifact)+'?device='+encodeURIComponent(profile.deviceConfigId)+'&context='+b.context:'/model/'+m.id}">View running instructions ${icon('arrow')}</a><button class="button secondary full" data-action="save">${icon('save')}${saved.some(x=>x.id===buildId(b))?'Saved in My builds':'Save this build'}</button><a class="inline-link summary-source" href="/model/${m.id}#performance">Published hardware measurements ${icon('arrow')}</a><p class="micro-note">Capacity planning is separate from measured performance. Chat remains a UI preview.</p></aside>`;}

function composer(){const b=currentBuild,m=modelFor(b);return `<main class="page composer-page"><a class="back-link" href="/model/${m.id}">${icon('back')}${esc(m.name)}</a><div class="page-intro"><div><div class="eyebrow">MODEL → CONFIGURATION → DEVICE</div><h1>Make a plan for your hardware.</h1><p>Explore precision and context with explicit memory assumptions.</p></div></div><div class="composer-layout"><div class="composer-controls"><section class="card control-section"><span class="step-number">01</span><h2>Weight precision</h2><p>Higher precision needs more memory. Runtime support must be verified separately.</p><label class="field-label" for="quant-select">Quantization format</label><select id="quant-select">${quants.map(q=>`<option value="${esc(q.id)}" ${q.id===b.quant?'selected':''}>${esc(q.id)} · ${esc(q.type)} · ${q.bits==null?'precision not specified':q.bits+'-bit'}</option>`).join('')}</select><p class="micro-note" id="quant-note">${quantFor(b).note}</p></section><section class="card control-section"><span class="step-number">02</span><h2>Working preset</h2><p>These are editable generation settings, not capability scores.</p><div class="choice-chips">${useCases.map(u=>`<button data-build-use="${u}" class="${b.use===u?'selected':''}">${u}</button>`).join('')}</div></section><section class="card control-section"><span class="step-number">03</span><h2>Context window</h2><p>${modelLimit(m)==null?(m.context_variants?.length?'Context differs by checkpoint. A verified checkpoint is needed for runtime assessment.':'Publisher context is unverified. The selected context is a manual planning assumption.'):'Documented context: '+ctx(m.context_length)+'. Longer context changes memory usage.'}</p><div class="context-options">${[...new Set([...hardware.contexts.map(Number),b.context])].sort((a,b)=>a-b).map(n=>`<button data-context="${n}" ${n>(modelLimit(m)??65536)?'disabled':''} class="${n===b.context?'selected':''}"><span>${n<=8192?'Small':n===16384?'Medium':n===32768?'Large':'Very large'}</span><strong>${ctx(n)}</strong><small>${n>(modelLimit(m)??65536)?'Beyond model limit':n+' tokens'}</small></button>`).join('')}</div></section><details class="card advanced"><summary>${icon('tune')}Generation settings ${icon('chevron')}</summary><div class="advanced-grid"><label>Temperature<input id="temperature" type="number" min="0" max="2" step=".05" required value="${b.temperature}"/></label><label>Top P<input id="top-p" type="number" min="0" max="1" step=".05" required value="${b.topP}"/></label><label class="wide">System prompt<textarea id="system-prompt" maxlength="1000" rows="3">${esc(b.systemPrompt)}</textarea></label></div></details><p class="fixture-note">Memory assessments come from the database for the selected device, format and context. A format without a stored result remains unassessed.</p></div><div id="summary">${summary(b)}</div></div></main>`;}
const suggestions={Coding:'Write a Python function that removes duplicates from a list while preserving order.',Thinking:'Explain why the sum of the first n odd numbers is n squared.',Writing:'Write a warm, concise email inviting a colleague to a coffee chat.',Chinese:'用一个生活中的例子，简单解释什么是递归。'};
function comparison(){return {...currentBuild,quant:currentBuild.quant==='Q4_K_M'?'Q5_K_M':'Q4_K_M'};}
function playground(){const b=currentBuild,m=modelFor(b);return `<main class="page playground-page"><div class="play-heading"><div><a class="back-link" href="${buildLink(b)}">${icon('back')}Back to your configuration</a><h1>${esc(m.name)}<span>${b.quant}</span></h1><p>${ctx(b.context)} context · ${profileLabel()} · Runtime performance not measured for this build</p></div><div class="play-mode segmented"><button data-mode="single" class="${!compare?'active':''}">Single</button><button data-mode="compare" class="${compare?'active':''}">Compare</button></div></div><div class="demo-banner">${icon('book')}<span><strong>UI preview</strong> — Replies are illustrative sample text. No live model is called; this is not a quality or speed benchmark.</span></div><div class="play-layout"><section class="chat-panel card"><div class="chat-toolbar"><span>${compare?'Configuration comparison':'Conversation preview'}</span><button class="text-button" data-action="clear-chat">Clear chat</button></div>${compare?`<div class="compare-header"><div><b>Build A</b>${b.quant}</div><div><b>Build B</b>${comparison().quant}</div></div>`:''}<div class="chat-messages ${compare?'comparing':''}" id="chat-messages" aria-live="polite">${chatContent()}</div>${compare&&chat.length?`<div class="vote"><span>Your preference, stored only in this browser.</span>${['A','Same','B'].map(v=>`<button data-vote="${v}" class="${vote===v?'selected':''}">${v==='Same'?'About the same':'Build '+v}</button>`).join('')}</div>`:''}<form id="chat-form"><label for="chat-input" class="sr-only">Your message</label><textarea id="chat-input" rows="2" placeholder="Try an example prompt…" maxlength="4000" ${busy?'disabled':''}></textarea><button class="icon-button send-button" type="submit" aria-label="Send message" ${busy?'disabled':''}>${icon('send')}</button><span>Enter to send · Shift + Enter for a new line</span></form></section><aside class="play-sidebar"><div class="card prompt-card"><div class="eyebrow">EXAMPLE PROMPTS</div><h2>Try the interface.</h2>${Object.keys(suggestions).map(s=>`<button data-suggestion="${s}">${icon(s==='Coding'?'code':'book')}${s}${icon('arrow')}</button>`).join('')}</div><div class="card play-build"><div class="eyebrow">THIS CONFIGURATION</div><h3>${esc(m.name)}</h3><p>${b.quant} · ${ctx(b.context)}</p>${memoryMeter(b,true)}<button class="button secondary full" data-action="save">${icon('save')}Save build</button></div></aside></div></main>`;}

function sampleReply(prompt,variant=false){const intro=variant?'Sample response B':'Sample response A';let answer;if(/递归|recurs/i.test(prompt))answer='递归就像打开一组俄罗斯套娃：每打开一个娃娃，里面还有一个更小的娃娃。你重复同一个动作，直到遇到最小的、不能再打开的娃娃。\n\n在程序中，函数调用自己来处理更小的问题；“最小的娃娃”就是停止递归的条件。';else if(/odd|squared|数学/i.test(prompt))answer='Picture a square made of dots. Start with 1 dot. Add an L-shaped border of 3 dots to make a 2 × 2 square. Add 5 more to make a 3 × 3 square.\n\nEach new border has the next odd number of dots. After n borders, the square has n² dots, so 1 + 3 + 5 + … + (2n − 1) = n².';else if(/python|duplicate/i.test(prompt))answer='For hashable items, a dictionary keeps the first occurrence in insertion order:\n\ndef unique_in_order(items):\n    return list(dict.fromkeys(items))\n\nunique_in_order([3, 1, 3, 2, 1])\n# [3, 1, 2]\n\nThis runs in O(n) average time. For unhashable items, such as lists, use equality checks instead.';else if(/email|coffee/i.test(prompt))answer='Subject: Coffee this week?\n\nHi Alex,\n\nI’d love to catch up over coffee sometime this week. Are you free for 20 minutes on Thursday afternoon? Happy to work around your schedule.\n\nLooking forward to it!';else answer='This is a sample reply from the frontend preview.\n\nYour message is ready for the future inference service, together with this build’s model, quant, context, temperature, and system prompt. No model has been called.\n\nTry one of the example prompts on the right to explore a complete sample conversation.';return `${intro} · simulated\n\n${answer}${variant?'\n\nThis comparison uses illustrative text, not measured differences between quants.':''}`;}
function chatContent(){if(!chat.length)return `<div class="chat-empty"><div class="empty-mark">${icon('spark')}</div><h2>See how your build feels.</h2><p>Try a question, a piece of code, or a fresh idea.</p><span>Sample conversation · nothing sent to a server</span></div>`;return chat.map(x=>`<div class="chat-turn"><div class="user-message"><b>You</b><p>${esc(x.prompt)}</p></div><div class="answer-grid"><div class="assistant-message"><span>${icon('spark')} ${compare?'Build A':'MacFit preview'}</span><p>${esc(x.answer||'Preparing sample reply…')}</p></div>${compare?`<div class="assistant-message"><span>${icon('spark')} Build B</span><p>${esc(x.answerB||'Preparing sample reply…')}</p></div>`:''}</div></div>`).join('');}
function modal(content,cls=''){
 document.querySelector('#dialogs').innerHTML=`<dialog class="modal ${cls}" aria-labelledby="dialog-title"><button class="icon-button modal-close" data-action="close" aria-label="Close dialog">${icon('close')}</button>${content}</dialog>`;
 const d=document.querySelector('dialog');d.showModal();
 d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});
}
function openProfile(){modal(`<h2 id="dialog-title">Your device</h2><div class="mac-picker">${picker(true)}</div>`,'profile-modal');document.querySelector('dialog').addEventListener('close',()=>document.querySelector('.profile-button')?.focus(),{once:true});}
function refreshProfile(){
 const active=document.activeElement,field=active?.dataset?.field,memory=active?.dataset?.memory;
 write('macfit.profile',profile);listPage=1;if(location.pathname==='/for-your-device')updateQuery();render();
 const p=document.querySelector('dialog[open] .mac-picker');if(p)p.innerHTML=picker(true);
 if(p&&field)p.querySelector(`[data-field="${field}"]`)?.focus();
 if(p&&memory)p.querySelector(`[data-memory="${memory}"]`)?.focus();
}
function openSaved(){modal(`<div class="eyebrow">SAVED CONFIGURATIONS</div><h2 id="dialog-title">My builds <span>${saved.length}</span></h2><p class="muted-text">Stored only in this browser.</p><div class="saved-list">${saved.length?saved.map(x=>{const b=parseBuild(x.id),m=modelFor(b);return `<div class="saved-item">${logo(m)}<div><h3>${esc(m.name)}</h3><p>${esc(b.quant)} · ${ctx(b.context)} · ${esc(b.use)}</p></div><a class="button primary small-button" href="${b.artifact?'/run/'+encodeURIComponent(b.artifact)+'?device='+encodeURIComponent(profile.deviceConfigId)+'&context='+b.context:'/build/'+x.id}">Instructions</a><a class="icon-button" href="/build/${x.id}" aria-label="Edit ${esc(m.name)}">${icon('tune')}</a><button class="icon-button" data-remove="${x.id}" aria-label="Remove ${esc(m.name)}">${icon('close')}</button></div>`;}).join(''):'<div class="empty"><h3>No saved builds yet.</h3><p>Start with a model and save a configuration.</p><a class="button primary" href="/models">Browse models</a></div>'}</div>`,'saved-modal');}
function openWizard(){modal(`<div class="eyebrow">A POPULAR MODEL, A STARTING CONFIGURATION</div><h2 id="dialog-title">What do you want to work on?</h2><p class="muted-text">We’ll choose from recorded planning candidates for your selected device at 8K context.</p><div class="wizard-options">${[['General','Text generation'],['Coding','Coding'],['Thinking','Thinking'],['RAG','Tools & retrieval workflow']].map(([value,label])=>`<button data-wizard-use="${value}" class="${wizardUse===value?'selected':''}" aria-pressed="${wizardUse===value}">${icon(value==='Coding'?'code':'book')}${label}<span class="wizard-check">${icon('check')}</span></button>`).join('')}</div><label class="field-label">Precision preference</label><div class="choice-chips">${['Best Quality','Balanced','Lowest Memory'].map(p=>`<button data-wizard-pref="${p}" class="${p===wizardPreference?'selected':''}">${p}</button>`).join('')}</div><button class="button primary full" data-action="create-build">Create a starting plan ${icon('arrow')}</button>`,'wizard-modal');}
function saveBuild(){if(!currentBuild)return;const id=buildId(currentBuild);if(!saved.some(s=>s.id===id)){const next=[...saved,{id,profile:{...profile},savedAt:new Date().toISOString()}];if(!writeSavedBuilds(next))return;saved=next;}if(document.querySelector('#saved-count'))document.querySelector('#saved-count').textContent=saved.length;document.querySelector('#summary')&&(document.querySelector('#summary').innerHTML=summary(currentBuild));toast('Configuration saved in this browser');}
function syncBuild(){history.replaceState({},'',buildLink(currentBuild));document.querySelector('#summary').innerHTML=summary(currentBuild);const note=document.querySelector('#quant-note');if(note)note.textContent=quantFor(currentBuild).note;ensureMatches();}
function navigate(href){document.querySelector('dialog')?.close();history.pushState({},'',href);chatRun++;busy=false;chat=[];render(true);window.scrollTo(0,0);scrollHash();}
function scrollHash(){if(location.hash&&/^#[a-z-]+$/.test(location.hash))document.querySelector(location.hash)?.scrollIntoView();}
function notFound(){return '<main class="page"><div class="empty not-found"><h1>We can’t find that model or build.</h1><p>Try the model catalog to create a new configuration.</p><a class="button primary" href="/models">Browse models</a></div></main>';}
function render(focus=false){
 disposePageFocus?.();disposePageFocus=null;
 disposeRecommendation?.();disposeRecommendation=null;
 let path=location.pathname,params=new URLSearchParams(location.search);
 if(path==='/for-your-mac'){
  const old=params.get('use');const aliases={Overall:'all',Coding:'coding',Reasoning:'thinking',Math:'thinking',Writing:'text-generation',Chinese:'text-generation'};
  const dest=params.get('view')==='models'?'/models':'/for-your-device';
  params=new URLSearchParams(old?{category:aliases[old]||'all'}:{});history.replaceState({},'',dest+(params.size?'?'+params:''));path=dest;
 }
 let html,title='Your computer. Your model.';
 if(path==='/')html=home();
 else if(path==='/for-your-device'){html=recommendationShell();title='For your device';}
 else if(path==='/teach'||(path.startsWith('/customize/')&&!params.has('edit'))){html=teachingShell();title='Teach your model';}
 else if(path==='/my-models'||path.startsWith('/my-models/')||path.startsWith('/customize/')||path.startsWith('/optimize/')){html=personalShell();title=path.startsWith('/customize/')?'Make it mine':path.startsWith('/optimize/')?'Fit your computer':'My models';}
 else if(path.startsWith('/run/')){html=recommendationShell();title='Running instructions';}
 else if(path==='/models'){
  if(path==='/for-your-device'){const requested=configRows().find(c=>c.id===params.get('device'));if(requested)profile=profileFromConfiguration(requested);const n=Number(params.get('context'));if(hardware.contexts.map(Number).includes(n))deviceContext=n;}
  category=catalog.categories.some(c=>c.id===params.get('category'))?params.get('category'):'all';
  sort=['popular','smallest','newest','updated'].includes(params.get('sort'))?params.get('sort'):'popular';
  publisher=params.get('publisher')||'all';listPage=Math.max(1,Math.floor(Number(params.get('page'))||1));fitFilter=['planning_candidate','insufficient_memory','unknown'].includes(params.get('fit'))?params.get('fit'):'all';
  search=params.get('q')||'';html=listing(path==='/models');title=path==='/models'?'Model catalog':'For your device';
 }else if(path.startsWith('/model/')){const m=catalog.models.find(m=>m.id===path.split('/')[2]);html=m?detail(m):notFound();title=m?.name||'Model not found';}
 else if(path.startsWith('/build/')||path.startsWith('/play/')){
  const id=path.split('/')[2],m=catalog.models.find(m=>m.id===id);currentBuild=parseBuild(id)||(m&&!isEmbedding(m)?defaultBuild(m,profile):null);
  vote=currentBuild?read('macfit.vote.'+buildId(currentBuild),''):'';
  html=!profileConfirmed()?'<main class="page"><div class="empty card"><h1>Confirm your computer before planning a build.</h1><p>A saved or shared build does not confirm your hardware.</p><a class="button primary" href="/for-your-device?edit=device">Confirm device</a></div></main>':currentBuild?(path.startsWith('/build/')?composer():playground()):notFound();title=currentBuild?modelFor(currentBuild).name+' · '+currentBuild.quant:'Build not found';
 }else html=notFound();
 document.title=title+' — MacFit';app.innerHTML=header()+html;
 if(path==='/for-your-device'||path.startsWith('/run/')){matchController?.abort();const props={catalog,hardware,fetchCompatibility,onForget:()=>{const el=document.querySelector('.site-header');if(el)el.outerHTML=header();},onConfirm:config=>{profile=profileFromConfiguration(config);write('macfit.profile',profile);const headerEl=document.querySelector('.site-header');if(headerEl)headerEl.outerHTML=header();}};disposeRecommendation=path==='/for-your-device'?mountFind(document.querySelector('#recommendation-page'),props):mountLocalRun(document.querySelector('#recommendation-page'),props);}
 else if(path==='/teach'||(path.startsWith('/customize/')&&!params.has('edit')))disposeRecommendation=mountTeaching(document.querySelector('#teach-page'),{catalog,hardware});
 else if(path==='/my-models'||path.startsWith('/my-models/')||path.startsWith('/customize/')||path.startsWith('/optimize/'))disposeRecommendation=mountPersonal(document.querySelector('#mine-page'),{catalog,hardware,fetchCompatibility});
 else if((path.startsWith('/build/')||path.startsWith('/play/'))&&profileConfirmed())ensureMatches();
 else if(matchState.status==='loading'){matchController?.abort();matchController=null;matchState={key:null,status:'idle',items:[],error:null};}
 const main=app.querySelector('main');if(main){main.id='main-content';main.setAttribute('tabindex','-1');}
 if(focus)disposePageFocus=focusAfterNavigation(app);
}
function updateQuery(){const p=new URLSearchParams();if(location.pathname==='/for-your-device'){p.set('device',profile.deviceConfigId);p.set('context',String(deviceContext));if(fitFilter!=='all')p.set('fit',fitFilter);}if(category!=='all')p.set('category',category);if(sort!=='popular')p.set('sort',sort);if(publisher!=='all')p.set('publisher',publisher);if(search)p.set('q',search);if(listPage>1)p.set('page',String(listPage));history.replaceState({},'',location.pathname+(p.size?'?'+p:''));}
function updateList(){if(!isCatalog()){refreshDatabaseSections();return;}document.querySelector('#model-grid').innerHTML=listCards(true);document.querySelector('#result-count').textContent=fmt(filteredModels().length,0)+' models';document.querySelector('#catalog-pages').innerHTML=paginationMarkup(filteredModels());}
function commitProfileInputs(){return write('macfit.profile',profile);}
function chooseConfiguration(id){const c=configRows().find(c=>c.id===id);if(c){profile=profileFromConfiguration(c);refreshProfile();}}
window.addEventListener('popstate',()=>{chatRun++;busy=false;chat=[];render(true);scrollHash();});
document.addEventListener('click',e=>{
 if(!e.target.closest('.account-menu'))closeAccountMenu();
 const a=e.target.closest('a');if(a?.hasAttribute('download'))return;if(a&&!a.hasAttribute('download')&&!e.defaultPrevented&&a.origin===location.origin&&['http:','https:'].includes(a.protocol)&&!a.target&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&e.button===0){if(a.pathname===location.pathname&&a.hash)return;e.preventDefault();navigate(a.pathname+a.search+a.hash);return;}
 const button=e.target.closest('button');if(!button||button.hasAttribute('data-lesson'))return;const d=button.dataset;
 if(d.action==='account'){const panel=document.querySelector('#account-panel');if(panel){const open=panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',String(open));}return;}
 if(d.action==='google-signin'){void signInGoogle();return;}
 if(d.action==='google-signout'){void signOutAccount();return;}
 if(d.action==='profile'){navigate('/for-your-device?edit=device');return;}
 if(d.action==='close')document.querySelector('dialog')?.close();
 if(d.action==='saved')openSaved();
 if(d.action==='wizard'){navigate('/for-your-device');return;}
 if(d.action==='save')saveBuild();
 if(d.action==='find'){if(!commitProfileInputs(button.closest('.mac-picker')))return;navigate('/for-your-device');}
 if(d.action==='save-profile'){if(!commitProfileInputs(button.closest('.mac-picker')))return;document.querySelector('dialog')?.close();render();document.querySelector('.profile-button')?.focus();toast('Device profile saved');}
 if(d.family){const options=configRows().filter(c=>(c.chip.memory_kind==='unified'?'mac':'pc')===d.family);const preferred=options.find(c=>c.id==='apple-m6-16gb')||options[0];if(preferred)chooseConfiguration(preferred.id);}
 if(d.config)chooseConfiguration(d.config);
 if(d.action==='refresh-matches')ensureMatches(true);
 if(d.action==='show-all-fits'){fitFilter='all';listPage=1;updateQuery();const el=document.querySelector('#fit-filter');if(el)el.value='all';refreshDatabaseSections();}
 if(d.category){category=d.category;listPage=1;updateQuery();render();document.querySelector(`[data-category="${category}"]`)?.focus();}
 if(d.sort){sort=d.sort;listPage=1;updateQuery();render();document.querySelector(`[data-sort="${sort}"]`)?.focus();}
 if(d.action==='reset-filters'){search='';category='all';publisher='all';sort='popular';fitFilter='all';listPage=1;updateQuery();render();}
 if(d.page){listPage=Number(d.page);updateQuery();updateList();document.querySelector('#result-count')?.scrollIntoView({block:'start'});}
 if(d.context){currentBuild.context=+d.context;document.querySelectorAll('[data-context]').forEach(b=>b.classList.toggle('selected',b===button));syncBuild();}
 if(d.buildUse){const p=presets[d.buildUse];currentBuild={...currentBuild,use:d.buildUse,context:Math.min(p.context,modelLimit(modelFor(currentBuild))??8192),temperature:p.temperature,systemPrompt:p.prompt};history.replaceState({},'',buildLink(currentBuild));render();}
 if(d.remove){const next=saved.filter(s=>s.id!==d.remove);if(writeSavedBuilds(next)){saved=next;if(document.querySelector('#saved-count'))document.querySelector('#saved-count').textContent=saved.length;openSaved();}}
 if(d.wizardUse){wizardUse=d.wizardUse;document.querySelectorAll('[data-wizard-use]').forEach(b=>{b.classList.toggle('selected',b.dataset.wizardUse===wizardUse);b.setAttribute('aria-pressed',String(b.dataset.wizardUse===wizardUse));});}
 if(d.wizardPref){wizardPreference=d.wizardPref;document.querySelectorAll('[data-wizard-pref]').forEach(b=>b.classList.toggle('selected',b.dataset.wizardPref===wizardPreference));}
 if(d.action==='create-build')createDatabaseBuild(button);

 if(d.suggestion){const input=document.querySelector('#chat-input');if(input&&!busy){input.value=suggestions[d.suggestion];input.focus();}}
 if(d.mode){compare=d.mode==='compare';render();}
 if(d.vote){vote=d.vote;write('macfit.vote.'+buildId(currentBuild),vote);render();}
 if(d.action==='clear-chat'){chatRun++;busy=false;chat=[];render();}
 if(d.action==='retry')boot();
});
document.addEventListener('input',e=>{
 if(e.target.id==='model-search'){search=e.target.value;listPage=1;updateQuery();updateList();return;}
 const field=e.target.dataset.field;
 if(['gpu','memory','vram'].includes(field)&&e.target.checkValidity())profile[field]=field==='gpu'?e.target.value:e.target.value?+e.target.value:null;
 const prop={temperature:'temperature','top-p':'topP','system-prompt':'systemPrompt'}[e.target.id];
 if(prop&&e.target.checkValidity()){currentBuild[prop]=prop==='systemPrompt'?e.target.value:+e.target.value;syncBuild();}
});
document.addEventListener('change',e=>{
 const field=e.target.dataset.field;
 if(field==='db-chip'){const c=hardware.items.find(c=>c.id===e.target.value);const memory=selectedConfiguration()?.ram_gib??selectedConfiguration()?.vram_gib;const config=c?.configurations.find(d=>(d.ram_gib??d.vram_gib)===memory)||c?.configurations[0];if(config)chooseConfiguration(config.id);return;}
 if(e.target.id==='device-context'){deviceContext=Number(e.target.value);listPage=1;write('macfit.context',deviceContext);updateQuery();ensureMatches();return;}
 if(e.target.id==='fit-filter'){fitFilter=e.target.value;listPage=1;updateQuery();refreshDatabaseSections();return;}
 if(e.target.id==='publisher-filter'){publisher=e.target.value;listPage=1;updateQuery();updateList();return;}
 if(e.target.id==='model-sort'){sort=e.target.value;listPage=1;updateQuery();updateList();return;}
 if(e.target.id==='quant-select'){currentBuild.quant=e.target.value;delete currentBuild.artifact;syncBuild();return;}
 const prop={temperature:'temperature','top-p':'topP','system-prompt':'systemPrompt'}[e.target.id];
 if(prop){if(!e.target.checkValidity()){e.target.reportValidity();return;}currentBuild[prop]=prop==='systemPrompt'?e.target.value:+e.target.value;syncBuild();}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#account-panel:not([hidden])')){e.preventDefault();closeAccountMenu(true);return;}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('#chat-form').requestSubmit();}});
document.addEventListener('submit',e=>{
 if(e.target.id!=='chat-form')return;e.preventDefault();if(busy)return;
 const text=document.querySelector('#chat-input').value.trim();if(!text)return;
 busy=true;const run=++chatRun;chat.push({prompt:text,answer:'',answerB:''});render();
 setTimeout(()=>{if(run!==chatRun)return;chat.at(-1).answer=sampleReply(text);chat.at(-1).answerB=sampleReply(text,true);busy=false;render();document.querySelector('#chat-messages').scrollTop=1e9;document.querySelector('#chat-input').focus();},400);
});
async function createDatabaseBuild(button){
 const dialog=button.closest('dialog'),configId=profile.deviceConfigId;button.disabled=true;button.textContent='Checking recorded options…';
 try{
  const result=await fetchCompatibility(configId,8192,{verdict:'planning_candidate'});
  if(!dialog?.isConnected||!dialog.open||configId!==profile.deviceConfigId)return;
  const cap={General:'text-generation',Coding:'coding',Thinking:'thinking',RAG:'tools'}[wizardUse];
  const groups=groupAssessments(result.items);const candidates=catalog.models.filter(m=>!isEmbedding(m)&&m.task_tags?.includes(cap)&&preferredOption(groups.get(m.id)||[],wizardPreference)).sort((a,b)=>(b.downloads_30d||0)-(a.downloads_30d||0));
  const m=candidates[0];if(!m){toast('No recorded candidates for this task and device. Try another configuration.');return;}
  const row=preferredOption(groups.get(m.id),wizardPreference),preset=presets[wizardUse];
  navigate(buildLink({...buildFromAssessment(m,row),use:wizardUse,temperature:preset.temperature,systemPrompt:preset.prompt}));toast('Created from a recorded planning candidate');
 }catch{toast('The database could not be reached. Please retry.');}
 finally{if(button.isConnected){button.disabled=false;button.innerHTML='Create a starting plan '+icon('arrow');}}
}
async function boot(){try{
 app.innerHTML='<main id="main-content" class="page" tabindex="-1"><div class="empty not-found" role="status"><span class="loading-indicator"></span><h2>Loading model data…</h2></div></main>';
 await loadCatalog();registerArtifactQuants(catalog.artifacts);
 const proof=read('macfit.recommendation.profile',null);const initial=configRows().find(c=>c.id===proof?.deviceId&&proof.confirmed===true)||configRows().find(c=>c.id===profile?.deviceConfigId)||configRows().find(c=>c.id==='apple-m6-16gb')||configRows()[0];if(!initial)throw new Error('No hardware configurations available');profile=profileFromConfiguration(initial);if(!hardware.contexts.map(Number).includes(deviceContext))deviceContext=8192;
 const existing=read('macfit.builds',[]);saved=Array.isArray(existing)?existing.filter(x=>x&&parseBuild(x.id)):[];
 render();scrollHash();
}catch(error){app.innerHTML=`<main id="main-content" class="page" tabindex="-1"><div class="empty not-found"><h1>Model data isn’t available yet.</h1><p>The model data service could not be reached. Please retry.</p><button class="button primary" data-action="retry">Reload model data</button></div></main>`;console.error(error);}}
subscribeAccount(refreshAccountUI);
document.addEventListener('macfit:account-changed',event=>{
 // A retry can restore an account after a local workspace was already opened.
 // Preserve the initial deep link, but refresh that workspace after recovery.
 if((event.detail?.initial&&!event.detail?.recovered)||!catalog.models.length)return;
 const path=location.pathname;
 if(path.startsWith('/my-models')||path==='/teach'||path.startsWith('/customize/')){
   navigate('/my-models');
 }
});
void initializeAccount();
boot();
